insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_9_v1'
from (values
('127.53.d.1.A',2,'A student in floral design wants to explore jobs. Which choice names real career paths?','["Floral designer, florist shop owner, or event decorator", "Court reporter only", "Airline pilot only", "Plumber only"]'::jsonb,0,'Floral design leads to jobs in shops, events and wholesale, including owning a business.','original'),
('127.53.d.1.A',3,'Which step best helps a floral design student plan an entrepreneurship path?','["Choosing a name only", "Researching what it costs to open a flower shop", "Avoiding all business classes", "Waiting for a shop to appear"]'::jsonb,1,'Start-up costs, supply sources and customers are key facts for planning.','original'),
('127.53.d.1.B',2,'In a flower shop, which habit shows professionalism?','["Leaving a messy workbench", "Arriving late", "Greeting customers politely and finishing orders on time", "Ignoring phone orders"]'::jsonb,2,'Courtesy and reliability build customer trust.','original'),
('127.53.d.1.B',3,'A designer realizes a wedding order is short of roses. A professional response is to:','["Cancel without telling anyone", "Use any flower without asking", "Hide the shortage", "Tell the supervisor and look for a substitute that fits the design"]'::jsonb,3,'Solving problems and communicating protects the customer relationship.','original'),
('127.53.d.1.C',2,'Why should floral workers use sharp tools carefully and keep stems away from their faces?','["To prevent cuts and eye injuries", "To make arrangements taller", "To save water", "To keep flowers warm"]'::jsonb,0,'Knives, shears and wire can cause injuries if used carelessly.','original'),
('127.53.d.1.C',3,'Which is a safe habit in a floral workshop?','["Walking with open scissors", "Wearing gloves when handling wire and thorny stems", "Using broken tools", "Leaving wet floors unmarked"]'::jsonb,1,'Protective gear and tidy spaces reduce accidents.','original'),
('127.53.d.1.D',3,'A florist who follows laws about advertising and fair pricing is practicing:','["Hiding costs", "Copying competitors'' names", "Ethical business conduct", "Illegal discounting"]'::jsonb,2,'Honest pricing and advertising are legal and ethical duties.','original'),
('127.53.d.1.D',4,'An employee in a floral shop has the responsibility to:','["Skip safety rules", "Take stock home", "Share customer details online", "Treat customer information and orders with care"]'::jsonb,3,'Confidentiality and honesty are workplace duties.','original'),
('127.53.d.1.E',2,'Which shows good citizenship in the floral industry?','["Donating arrangements for a community event", "Refusing to share space", "Ignoring community needs", "Littering at the market"]'::jsonb,0,'Giving back to the community builds goodwill.','original'),
('127.53.d.1.E',3,'A responsible florist disposes of plant waste by:','["Burning it in a parking lot", "Composting or recycling it where possible", "Dumping it in a creek", "Leaving it in the street"]'::jsonb,1,'Responsible disposal protects the environment.','original'),
('127.53.d.2.A',3,'A student sets up a plan to design arrangements for a local event and track sales for a term. This is a:','["Class schedule", "Field trip permission slip", "Supervised agricultural experience in floral design", "Pop quiz"]'::jsonb,2,'An SAE is a planned, supervised, hands-on project with goals.','original'),
('127.53.d.2.A',2,'Who oversees a student''s floral design project?','["A random website", "Only the customer", "No one", "A teacher or other supervising adult"]'::jsonb,3,'Adult supervision guides and checks the work.','original'),
('127.53.d.2.B',2,'Why should a floral design student record costs of stems and sales of arrangements?','["To see profit and show what was learned", "To hide results", "So records are lost", "To make the shop look busy"]'::jsonb,0,'Records show progress, costs and income.','original'),
('127.53.d.2.B',3,'Which belongs in a floral SAE record book?','["A movie list", "A log of arrangements made, with materials and prices", "A grocery list only", "A list of unrelated hobbies"]'::jsonb,1,'Dated, specific records support evaluation.','original'),
('127.53.d.3.A',2,'Which activity builds leadership for a floral design student?','["Skipping all events", "Avoiding teamwork", "Leading a flower-arranging booth at a school event", "Watching quietly"]'::jsonb,2,'Leading a group project builds skills.','original'),
('127.53.d.3.B',2,'A chapter''s program of activities for floral design members could include:','["Cancelling meetings", "Dropping all service", "Keeping plans private", "A flower sale fundraiser"]'::jsonb,3,'A program of activities lists planned events for the year.','original'),
('127.53.d.3.B',3,'Members who help plan and run the flower sale are:','["Participating in the local program of activities", "Resigning", "Avoiding service", "Breaking rules"]'::jsonb,0,'Joining planned events supports the chapter.','original'),
('127.53.d.3.C',2,'A resume for a floral design student might include:','["Nothing from class", "Designs created and volunteer events", "Only favorite colors", "Unrelated jokes"]'::jsonb,1,'Documented experience shows skills.','original'),
('127.53.d.3.C',3,'Why update a portfolio of floral experience each term?','["To make it shorter", "Because it does not matter", "So it stays current for jobs and scholarships", "To lose old work"]'::jsonb,2,'Current records support applications.','original'),
('127.53.d.4.A',3,'Why do floral design students study the history of floral art?','["To avoid design practice", "To memorize prices", "To skip color theory", "To see how styles changed over time and why"]'::jsonb,3,'History explains the origin of traditional styles.','original'),
('127.53.d.4.A',4,'A style that uses a tall, symmetrical mass of flowers in the old European tradition is called:','["Traditional or formal design", "Pressed art", "Minimalist ikebana", "Abstract design"]'::jsonb,0,'Historical European styles favored full, symmetrical arrangements.','original'),
('127.53.d.4.B',2,'Which of these is an element of floral design?','["Proportion", "Color", "Balance", "Rhythm"]'::jsonb,1,'Elements include color, texture, form, line and space; rhythm, balance and proportion are principles.','original'),
('127.53.d.4.B',3,'A rough, fuzzy flower paired with smooth leaves shows contrast in:','["Pattern of the vase", "Weight", "Texture", "Price"]'::jsonb,2,'Texture is how the surface looks and feels.','original'),
('127.53.d.4.C',2,'Which of these is a principle of floral design?','["Space", "Line", "Color", "Balance"]'::jsonb,3,'Principles include balance, rhythm and proportion.','original'),
('127.53.d.4.C',3,'An arrangement that looks equal on both sides has:','["Symmetrical balance", "Asymmetrical balance only", "No balance", "Random balance"]'::jsonb,0,'Symmetrical balance mirrors each side.','original'),
('127.53.d.4.D',3,'Emphasis in floral design is created by:','["Removing all color", "Making one area or flower stand out", "Using no focal point", "Making everything identical"]'::jsonb,1,'A focal area draws the eye.','original'),
('127.53.d.4.D',4,'A focal point is usually placed:','["At the very bottom edge", "Outside the container", "Where the eye is naturally drawn, often near the center", "Hidden behind leaves"]'::jsonb,2,'The focal point anchors the design.','original'),
('127.53.d.4.E',3,'Line flowers such as snapdragons are used to:','["Be the vase", "Add scent only", "Fill every gap", "Create height and direction"]'::jsonb,3,'Line flowers define the outline of a design.','original'),
('127.53.d.4.E',4,'Mass flowers like roses and carnations provide:','["Bulk and color near the focal area", "Only vertical lines", "Only filler", "Nothing to the design"]'::jsonb,0,'Mass flowers add visual weight.','original'),
('127.53.d.5.A',3,'A floral foam block is used in fresh arrangements to:','["Add scent", "Hold stems in place and supply water", "Keep flowers dry", "Replace the vase"]'::jsonb,1,'Wet foam supports stems and provides moisture.','original'),
('127.53.d.5.A',4,'An arrangement is judged well made when it:','["Uses only one color", "Is tiny", "Uses design principles and holds up for its purpose", "Has no container"]'::jsonb,2,'Evaluation checks design and function.','original'),
('127.53.d.5.B',3,'A wreath made of silk flowers is an example of a design using:','["Live potted plants", "Fresh-cut flowers", "Seeds", "Permanent botanicals"]'::jsonb,3,'Permanent botanicals are artificial or preserved materials.','original'),
('127.53.d.5.B',4,'A benefit of permanent botanicals is that they:','["Last without water and need little care", "Attract pests", "Need daily watering", "Wilt in a day"]'::jsonb,0,'Silk and dried materials last much longer.','original'),
('127.53.d.5.C',3,'A boutonniere is typically worn:','["On a wrist", "On a lapel", "On a shoe", "On a belt"]'::jsonb,1,'It is a small flower worn on a jacket lapel.','original'),
('127.53.d.5.C',4,'A corsage is commonly worn:','["On a collar only", "On a hat only", "On the wrist or shoulder", "On a tie"]'::jsonb,2,'Wrist and shoulder corsages are common.','original'),
('127.53.d.5.D',3,'A floral design for a cultural holiday should:','["Avoid color", "Use random flowers", "Ignore the tradition", "Respect traditional colors and symbols"]'::jsonb,3,'Cultural knowledge ensures a meaningful design.','original'),
('127.53.d.5.D',4,'Red and white flowers are often used for which holiday arrangement?','["Valentine''s Day", "Halloween", "Thanksgiving", "Independence Day"]'::jsonb,0,'Red and white roses symbolize love at Valentine''s Day.','original'),
('127.53.d.5.E',3,'An interiorscape is a design that:','["Is an outdoor farm", "Uses plants and floral elements to decorate an indoor space", "Is a seed packet", "Is a vase only"]'::jsonb,1,'Interiorscapes arrange plants inside buildings.','original'),
('127.53.d.5.E',4,'When designing an interiorscape, the designer should consider:','["Only vase shape", "Only price", "Light, space, and plant care needs", "Only color"]'::jsonb,2,'Plants must suit the conditions of the room.','original'),
('127.53.d.6.A',3,'Explaining why a designer chose certain colors for a wedding bouquet is:','["Skipping evaluation", "Changing the order", "Hiding the work", "Justifying an artistic decision"]'::jsonb,3,'Designers should be able to explain their choices.','original'),
('127.53.d.6.A',4,'A designer feels a bouquet is too crowded. A reasoned revision is to:','["Remove or reposition stems to improve balance and space", "Ignore the problem", "Change the price", "Add more at random"]'::jsonb,0,'Evaluating design leads to improvements.','original'),
('127.53.d.6.B',3,'A judge appraising a floral design looks for:','["How loud the shop is", "Use of principles, craftsmanship, and condition", "The price tag only", "The vase brand only"]'::jsonb,1,'Appraisal weighs design quality and execution.','original'),
('127.53.d.6.B',4,'Which would lower the score of an arrangement?','["Fresh materials", "Clean stems", "Wilted flowers and visible mechanics", "Good proportion"]'::jsonb,2,'Visible wire or foam and wilting hurt quality.','original'),
('127.53.d.6.C',3,'A portfolio of floral work is useful because it:','["Keeps flowers fresh", "Replaces a resume entirely", "Hides skills", "Shows a designer''s best work to employers or customers"]'::jsonb,3,'Portfolios demonstrate ability.','original'),
('127.53.d.6.C',4,'A good portfolio entry includes:','["A clear photo and notes on materials and techniques", "No description", "A blurry photo", "Only a price"]'::jsonb,0,'Documentation adds value.','original'),
('127.53.d.6.D',3,'Reviewing a centerpiece for proportion means checking:','["The shop''s address", "Whether the arrangement size fits the container and setting", "The day of the week", "The color of the invoice"]'::jsonb,1,'Proportion relates sizes of parts to the whole.','original'),
('127.53.d.6.D',4,'A design where the flowers are twice as tall as the vase may be judged as having good proportion if:','["It is hidden", "It leans over", "It follows the common height-to-container guideline", "It uses no flowers"]'::jsonb,2,'A common guideline is 1.5 to 2 times the container size.','original'),
('127.53.d.7.A',3,'Specialty floral items for a funeral might include:','["Valentine''s candy", "Birthday balloons only", "Party hats", "Sprays and wreaths"]'::jsonb,3,'Sprays and wreaths are common sympathy designs.','original'),
('127.53.d.7.A',4,'A bridal bouquet is an example of a:','["Specialty design for a wedding", "Shipping box", "Seed tray", "Everyday vase"]'::jsonb,0,'Weddings need special designs like bouquets.','original'),
('127.53.d.7.B',3,'Creating a specialty design helps a designer:','["Lose creativity", "Expand artistic skills and offerings", "Stop learning", "Avoid customers"]'::jsonb,1,'New designs add range.','original'),
('127.53.d.7.B',4,'A designer who experiments with unusual materials is:','["Quitting", "Avoiding design", "Expanding artistic expression", "Breaking all rules"]'::jsonb,2,'Experimenting builds style.','original'),
('127.53.d.7.C',3,'Florist wire is used to:','["Water flowers", "Cut foam", "Clean vases", "Support stems and shape materials"]'::jsonb,3,'Wire strengthens weak stems.','original'),
('127.53.d.7.C',4,'Floral tape is used to:','["Wrap wired stems and make them look finished", "Hold water", "Add scent", "Cool flowers"]'::jsonb,0,'Stretchy tape covers wire and holds components together.','original'),
('127.53.d.7.D',3,'Floral shears should be:','["Used on wire only", "Kept clean and sharp and stored safely", "Thrown in a drawer", "Left dull"]'::jsonb,1,'Sharp, clean tools cut cleanly and safely.','original'),
('127.53.d.7.D',4,'Before cutting stems, a designer should:','["Use any tool", "Use teeth", "Use the proper tool for the material", "Bend until it breaks"]'::jsonb,2,'The right tool prevents damage and injury.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_9_v1'
from (values
('127.53.d.8.A',3,'A carnation is classified as a:','["Foliage plant", "Shrub", "Fern", "Cut flower"]'::jsonb,3,'Carnations are popular cut flowers.','original'),
('127.53.d.8.A',4,'Leatherleaf and ruscus are examples of:','["Foliage", "Line flowers", "Mass flowers", "Filler flowers"]'::jsonb,0,'Foliage supports and frames designs.','original'),
('127.53.d.8.B',3,'Cutting stems at an angle under water helps cut flowers:','["Wilt sooner", "Take up water longer", "Grow roots", "Lose color"]'::jsonb,1,'Angled cuts increase water uptake.','original'),
('127.53.d.8.B',4,'Flower preservatives extend vase life by:','["Adding color", "Replacing water", "Providing sugar and slowing bacteria", "Making stems rigid"]'::jsonb,2,'Preservatives feed and keep water clean.','original'),
('127.53.d.8.C',3,'Why store flowers in a cooler?','["To change their color", "To make them bloom faster", "To dry them", "Cool temperatures slow aging"]'::jsonb,3,'Cold slows respiration and extends life.','original'),
('127.53.d.8.C',4,'Chemicals used in a flower shop must be:','["Used and stored according to their labels", "Used without gloves", "Left uncapped", "Mixed randomly"]'::jsonb,0,'Labels give safe instructions.','original'),
('127.53.d.8.D',3,'A houseplant that wilts in a dark corner likely needs:','["Salt", "More light", "A smaller pot only", "Less air"]'::jsonb,1,'Plants need enough light to photosynthesize.','original'),
('127.53.d.8.D',4,'Overwatering an indoor plant can cause:','["Faster growth always", "Better flowers", "Root rot", "Stronger stems"]'::jsonb,2,'Too much water deprives roots of oxygen.','original'),
('127.53.d.8.E',3,'Aphids on a plant are examples of:','["Fertilizer", "Flowers", "Containers", "Pests"]'::jsonb,3,'Aphids suck plant sap and harm growth.','original'),
('127.53.d.8.E',4,'Gray fuzzy mold on petals is often caused by:','["Botrytis fungus", "A weak vase", "Lack of wire", "Too much light"]'::jsonb,0,'Botrytis thrives in damp conditions.','original'),
('127.53.d.8.F',3,'One way to manage pests in a flower shop is to:','["Mix all stock together", "Keep the area clean and inspect incoming stock", "Ignore plants", "Add more water daily"]'::jsonb,1,'Sanitation and inspection prevent infestations.','original'),
('127.53.d.8.F',4,'Removing and discarding infected plants helps to:','["Spread it", "Add water", "Stop disease from spreading", "Improve color"]'::jsonb,2,'Isolation prevents the spread of pathogens.','original'),
('127.53.d.9.A',3,'A cost-effective design uses:','["Waste of materials", "Only rare imported flowers", "The costliest vase", "Seasonal flowers that are locally available"]'::jsonb,3,'Seasonal stock keeps costs lower.','original'),
('127.53.d.9.A',4,'A designer reduces cost without hurting quality by:','["Using fewer, well-chosen focal flowers with filler", "Skipping design", "Doubling the price", "Using no flowers"]'::jsonb,0,'Smart selection saves money.','original'),
('127.53.d.9.B',3,'A common florist pricing method adds labor and overhead to:','["The weather", "The cost of materials", "The shop''s color", "The customer''s age"]'::jsonb,1,'Prices cover materials, labor and overhead plus profit.','original'),
('127.53.d.9.B',4,'A customer with a $40 budget asks for a large centerpiece. The designer should:','["Refuse politely without options", "Charge $200", "Offer options that fit the budget", "Ignore the budget"]'::jsonb,2,'Matching designs to budgets keeps customers happy.','original'),
('127.53.d.9.C',3,'Delivery of fragile arrangements requires:','["Rough handling", "Stacking boxes", "No box", "Careful packaging and stable transport"]'::jsonb,3,'Protection avoids damage.','original'),
('127.53.d.9.C',4,'Setting up flowers at an event should be planned to:','["Arrive on time and have enough staff and supplies", "Start late", "Go unprepared", "Skip supplies"]'::jsonb,0,'Logistics make events run smoothly.','original'),
('127.53.d.10.A',3,'The leaves of an indoor plant carry out:','["Germination", "Photosynthesis", "Pollination", "Fertilization"]'::jsonb,1,'Leaves make food from light.','original'),
('127.53.d.10.A',4,'The roots of an indoor plant mainly:','["Make food", "Create fragrance", "Absorb water and nutrients and anchor the plant", "Produce seeds"]'::jsonb,2,'Roots take in water and support the plant.','original'),
('127.53.d.10.B',3,'The petals of a flower function to:','["Store seeds", "Anchor the plant", "Absorb water", "Attract pollinators"]'::jsonb,3,'Showy petals draw insects and birds.','original'),
('127.53.d.10.B',4,'The part of a flower that produces pollen is the:','["Anther", "Stigma", "Sepal", "Ovary"]'::jsonb,0,'The anther is part of the stamen.','original'),
('127.54.d.1.A',2,'A plant science student could choose a career such as:','["Pilot only", "Landscape designer, nursery grower, or arborist", "Court judge only", "Pastry chef only"]'::jsonb,1,'Horticulture offers many jobs with plants.','original'),
('127.54.d.1.A',3,'Starting a landscaping business is an example of:','["A school rule", "Government service", "Entrepreneurship in horticulture", "Required schooling"]'::jsonb,2,'Entrepreneurs run their own plant-related ventures.','original'),
('127.54.d.1.B',2,'Which shows professionalism in a nursery?','["Ignoring customers", "Leaving tools out", "Arriving late", "Completing tasks on time and following instructions"]'::jsonb,3,'Reliability matters in any job.','original'),
('127.54.d.1.B',3,'A crew member finds the irrigation timer broken. A professional response is to:','["Report it and suggest a temporary solution", "Hide it", "Break more", "Walk away"]'::jsonb,0,'Problem solving and communication keep the work going.','original'),
('127.54.d.1.C',2,'Why wear gloves and safety glasses when trimming shrubs?','["To look stylish", "To prevent cuts and eye injuries", "To save water", "To keep plants clean"]'::jsonb,1,'Protective gear reduces common injuries.','original'),
('127.54.d.1.C',3,'A safe practice when using power hedge trimmers is to:','["Remove the guard", "Use one-handed", "Wear hearing and eye protection and keep guards in place", "Run with them"]'::jsonb,2,'Guards and protective gear prevent accidents.','original'),
('127.54.d.1.D',3,'A nursery worker who follows laws about plant labeling is showing:','["Carelessness", "Disrespect", "Poor planning", "Ethical and legal conduct"]'::jsonb,3,'Honest labels protect customers.','original'),
('127.54.d.1.D',4,'A horticulture employee''s right is to:','["A safe workplace and fair pay", "Ignore rules", "Unsafe tools", "Unlimited breaks"]'::jsonb,0,'Workers have legal rights and duties.','original'),
('127.54.d.1.E',2,'A good citizen in horticulture might:','["Take plants without asking", "Plant trees for a community park", "Dump plant waste in a creek", "Ignore city rules"]'::jsonb,1,'Service and care for public spaces show citizenship.','original'),
('127.54.d.1.E',3,'Which practice shows environmental citizenship for a landscaper?','["Overwatering lawns", "Skipping recycling", "Using water wisely and avoiding excess runoff", "Washing chemicals down drains"]'::jsonb,2,'Efficient resource use protects the community.','original'),
('127.54.d.2.A',3,'A student grows tomato transplants to sell and keeps records for the term. This is a(n):','["Locker assignment", "Schedule change", "Spelling test", "Supervised agricultural experience in horticulture"]'::jsonb,3,'An SAE is a planned, supervised project.','original'),
('127.54.d.2.A',2,'An SAE in horticulture must have:','["A plan, goals, and a supervisor", "No records", "No plan", "No supervisor"]'::jsonb,0,'Plans and supervision are required.','original'),
('127.54.d.2.B',2,'Why record seed costs and sales for a plant project?','["To impress strangers", "To measure profit and learning", "To waste time", "To hide mistakes"]'::jsonb,1,'Records show results.','original'),
('127.54.d.2.B',3,'A plant SAE record could include:','["Movie reviews", "Nothing", "Dates planted, hours worked, and income", "Random doodles"]'::jsonb,2,'Complete records support evaluation.','original'),
('127.54.d.3.A',2,'Which activity helps build agricultural leadership in a horticulture class?','["Staying silent", "Letting others do all the work", "Skipping meetings", "Organizing a plant sale for the chapter"]'::jsonb,3,'Leading events builds skills.','original'),
('127.54.d.3.B',2,'A chapter''s local program of activities for horticulture could include:','["A community planting day", "Canceling service", "Keeping plans secret", "No meetings"]'::jsonb,0,'It lists the events members plan.','original'),
('127.54.d.3.B',3,'A member who helps with the plant sale is:','["Skipping service", "Participating in the program of activities", "Breaking rules", "Quitting"]'::jsonb,1,'Joining events supports the chapter.','original'),
('127.54.d.3.C',2,'An experience record for a horticulture student might include:','["Only grades", "Nothing", "Greenhouse volunteer hours", "Unrelated hobbies"]'::jsonb,2,'Documented experience shows skills.','original'),
('127.54.d.3.C',3,'Why update a record of plant experience each year?','["Because it is optional always", "To shorten it", "To lose records", "To keep it current for jobs and applications"]'::jsonb,3,'Updated records support future opportunities.','original'),
('127.54.d.4.A',3,'The development of grafting in history is important because it:','["Allowed desirable plants to be reproduced reliably", "Ended farming", "Replaced soil", "Stopped plant growth"]'::jsonb,0,'Grafting spread the best varieties of fruit trees.','original'),
('127.54.d.4.A',4,'Historical advancements in horticulture, such as irrigation, led to:','["Fewer plants", "Greater yields and new growing regions", "No changes", "Less food"]'::jsonb,1,'Technology expanded production.','original'),
('127.54.d.4.B',3,'Arboriculture is the study of:','["Vegetables only", "Turf only", "Trees and shrubs", "Flowers only"]'::jsonb,2,'Arborists care for trees.','original'),
('127.54.d.4.B',4,'Olericulture is the branch of horticulture that deals with:','["Fruit crops", "Ornamental flowers only", "Turfgrass", "Vegetable crops"]'::jsonb,3,'Olericulture is vegetable production.','original'),
('127.54.d.4.C',3,'Which emerging technology helps growers save water?','["Drip irrigation with sensors", "Hand carrying buckets", "Ignoring moisture", "Flooding fields"]'::jsonb,0,'Sensors and drip lines target water use.','original'),
('127.54.d.4.C',4,'Vertical farming is an example of:','["A pest", "An emerging growing technology", "A fertilizer", "An ancient tool"]'::jsonb,1,'It grows plants in stacked layers indoors.','original'),
('127.54.d.4.D',3,'A current trend in horticulture is increased interest in:','["Removing all plants", "Ignoring sustainability", "Native and pollinator-friendly plants", "Using only plastic"]'::jsonb,2,'Consumers want sustainable landscapes.','original'),
('127.54.d.4.D',4,'The growth of urban gardening shows a trend toward:','["Global shipping only", "Less food", "Fewer gardens", "Local food production"]'::jsonb,3,'People are growing food in cities.','original'),
('127.54.d.4.E',3,'Compared with East Texas, West Texas horticulture often needs:','["More irrigation and drought-tolerant plants", "More snow plants", "No water", "Tropical crops only"]'::jsonb,0,'Dry climates require water-efficient choices.','original'),
('127.54.d.4.E',4,'Citrus production in Texas is concentrated in the:','["Big Thicket", "Rio Grande Valley", "High Plains", "Panhandle"]'::jsonb,1,'The warm southern valley supports citrus.','original'),
('127.54.d.5.A',3,'Scientific names of plants use:','["Colors", "Spanish names", "Latin binomial names", "Nicknames only"]'::jsonb,2,'Genus and species names are used worldwide.','original'),
('127.54.d.5.A',4,'Using a scientific name instead of a common name helps because:','["It is a secret", "It is shorter", "It is always English", "Common names can refer to different plants"]'::jsonb,3,'Scientific names are precise.','original'),
('127.54.d.5.B',3,'The stems of a plant function mainly to:','["Support leaves and transport water and nutrients", "Make seeds", "Produce pollen", "Absorb light only"]'::jsonb,0,'Stems hold the plant up and carry fluids.','original'),
