('127.54.d.6.B',4,'Marigolds that complete their life cycle in one season are:','["Conifers", "Annuals", "Biennials", "Perennials"]'::jsonb,1,'Annuals live one growing season.','original'),
('127.54.d.6.C',3,'Identifying a tree by its leaf shape and bark is using:','["Pot color", "Price tag", "Physical characteristics", "Brand name"]'::jsonb,2,'Visible traits help identify plants.','original'),
('127.54.d.6.C',4,'Opposite leaf arrangement means leaves:','["Grow alone at each node", "Grow in spirals", "Do not grow", "Grow in pairs at the same node"]'::jsonb,3,'Opposite leaves are paired.','original'),
('127.54.d.6.D',3,'Non-flowering plants such as ferns reproduce by:','["Spores", "Seeds in fruits", "Bulbs only", "Flowers"]'::jsonb,0,'Ferns release spores.','original'),
